function generate(rand, size) {
  if (size === 'large') {
    const span = rand() < 0.5 ? 10000 : 5000 + Math.floor(rand() * 5001);
    const left = 1 + Math.floor(rand() * (1000000 - span));
    return [left, left + span];
  }
  const span = Math.floor(rand() * 40);
  const roll = rand();
  // Mostly small numbers, sometimes right next to the upper limit or around a power of two.
  let left;
  if (roll < 0.6) left = 1 + Math.floor(rand() * 80);
  else if (roll < 0.8) left = 1000000 - span - Math.floor(rand() * 50);
  else left = Math.max(1, (1 << (1 + Math.floor(rand() * 19))) - Math.floor(rand() * 20));
  left = Math.min(left, 1000000 - span);
  return [left, left + span];
}
